3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Flags a soft (possible) duplicate. The new owner is not a household duplicate — an existing owner
10	 * sharing its {@code householdId} would already have been rejected with 409 by
11	 * {@link CheckOwnerIdentityUnique}, unless the request declared {@code sharesHousehold} — but it may
12	 * still be a <em>likely</em> duplicate of an existing owner: same {@code lastName} (compared
13	 * case-insensitively) and same {@code postcode}, yet a different {@code telephone}.
14	 *
15	 * <p>A <em>declared</em> household member ({@code sharesHousehold = true}) is never a suspected
16	 * duplicate: it opted in explicitly, so it is left with {@code possibleDuplicate = false}. Otherwise,
17	 * when a matching existing owner is found, the new owner is still created but carries
18	 * {@code possibleDuplicate = true} and {@code possibleDuplicateOf} set to that existing owner's id;
19	 * when several match, the earliest (lowest id) is used for a deterministic result. Otherwise
20	 * {@code possibleDuplicate = false} and {@code possibleDuplicateOf} is left {@code null}.
21	 *
22	 * <p>Runs after {@link CheckOwnerIdentityUnique} (household duplicates already rejected) and before
23	 * {@link SaveOwner}, so the scan sees only the owners already persisted, not the new owner itself.
24	 */
25	public class AssignPossibleDuplicate {
26	
27	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
28	        owner.setPossibleDuplicate(false);
29	        owner.setPossibleDuplicateOf(null);
30	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
31	            return; // a declared household member is not a suspected duplicate
32	        }
33	        String lastName = owner.getLastName();
34	        String postcode = owner.getPostcode();
35	        String telephone = owner.getTelephone();
36	        if (postcode == null) {
37	            return; // no postcode to match on -> never a possible duplicate
38	        }
39	        Owner match = null;
40	        for (Owner existing : ownerRepository.findAll()) {
41	            if (Boolean.TRUE.equals(existing.getDeleted())) {
42	                continue; // a soft-deleted owner is not a possible duplicate
43	            }
44	            if (!equalsIgnoreCase(lastName, existing.getLastName())) {
45	                continue;
46	            }
47	            if (!postcode.equals(existing.getPostcode())) {
48	                continue;
49	            }
50	            if (equals(telephone, existing.getTelephone())) {
51	                continue; // same telephone is not a soft match (a hard match was already rejected)
52	            }
53	            if (match == null || lowerId(existing.getId(), match.getId())) {
54	                match = existing;
55	            }
56	        }
57	        if (match != null) {
58	            owner.setPossibleDuplicate(true);
59	            owner.setPossibleDuplicateOf(match.getId());
60	        }
61	    }
62	
63	    private static boolean lowerId(Integer candidate, Integer current) {
64	        if (candidate == null) {
65	            return false;
66	        }
67	        return current == null || candidate < current;
68	    }
69	
70	    private static boolean equalsIgnoreCase(String a, String b) {
71	        return a == null ? b == null : a.equalsIgnoreCase(b);
72	    }
73	
74	    private static boolean equals(String a, String b) {
75	        return a == null ? b == null : a.equals(b);
76	    }
77	}
