13	import org.springframework.samples.petclinic.rest.escalation.OwnerRegistrationDateFutureException;
14	import org.springframework.samples.petclinic.rest.escalation.OwnerTelephoneInvalidException;
15	import org.springframework.web.bind.annotation.RequestBody;
16	
17	/**
18	 * First step of {@code POST /api/owners}. Rejects a request that is missing or blank in any of
19	 * firstName, lastName, address, city or telephone, collecting every offending field name so the
20	 * response can list them all. The address may be given in structured form (addressLine1 [+
21	 * addressLine2]) or via the legacy flat 'address' field; it is composed and normalized first (see
22	 * {@link OwnerAddress#compose(String, String, String)}) and rejected when neither form yields a
23	 * non-blank value. It then normalizes the telephone into E.164 form (see
24	 * {@link OwnerTelephone#toE164(String)}), storing the normalized address lines, composed address and
25	 * telephone back on the body so they are persisted and
26	 * returned. On success it publishes the body for {@link BuildOwner} to consume
27	 * (only one step may bind {@code @RequestBody}).
28	 */
29	public class ValidateOwnerFields {
